#include <algorithm>
#include <string>
#include <vector>

void sortByLength(std::vector<std::string>& words)
{
    std::sort(words.begin(), words.end(), [](const std::string& a, const std::string& b)
    {
        if (a.length() != b.length())
        {
            return a.length() < b.length();
        }
        return a < b;
    });
}

unitTests:
TEST("shortest first") { std::vector<std::string> w{ "banana", "fig", "apple" }; sortByLength(w); CHECK_EQ(w, (std::vector<std::string>{ "fig", "apple", "banana" })); }
TEST("ties are alphabetical") { std::vector<std::string> w{ "dog", "cat", "ant", "bee" }; sortByLength(w); CHECK_EQ(w, (std::vector<std::string>{ "ant", "bee", "cat", "dog" })); }
TEST("mixed") { std::vector<std::string> w{ "bb", "a", "ccc", "aa", "c" }; sortByLength(w); CHECK_EQ(w, (std::vector<std::string>{ "a", "c", "aa", "bb", "ccc" })); }

